package com.agriconnect.analytics;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;
@RestController class ReadModelController{private final JdbcClient db;ReadModelController(JdbcClient d){db=d;}@GetMapping("/api/dashboard")Map<String,Object>dashboard(){return Map.of("cropBatches",count("crop_batch_snapshots"),"activeReservations",db.sql("select count(*) from inventory_snapshots where reserved_quantity>0").query(Long.class).single(),"orders",count("order_facts"),"shipments",count("shipment_facts"),"pendingRescues",db.sql("select count(*) from rescue_facts where status='PENDING'").query(Long.class).single());}@GetMapping("/api/analytics/inventory-risk")List<Map<String,Object>>risk(){return db.sql("select c.batch_id as \"batchId\",c.province,c.expiry_date as \"expiryDate\",i.available_quantity as \"availableQuantity\",case when c.expiry_date<=current_date+3 then 'HIGH' when c.expiry_date<=current_date+7 then 'MEDIUM' else 'LOW' end as risk from crop_batch_snapshots c join inventory_snapshots i on i.batch_id=c.batch_id order by c.expiry_date limit 100").query().listOfRows();}@GetMapping("/api/analytics/rescue-priority")List<Map<String,Object>>rescue(){return db.sql("select registration_id as \"registrationId\",crop_batch_id as \"cropBatchId\",farmer_id as \"farmerId\",rescue_point_id as \"rescuePointId\",status from rescue_facts order by case status when 'PENDING' then 0 else 1 end,updated_at desc limit 100").query().listOfRows();}private long count(String table){return db.sql("select count(*) from "+table).query(Long.class).single();}}
